{
  "API_calls": [],
  "collected_information": {
    "Environment_Setup": {
      "Python_Version": ">=3.10 and <3.13",
      "Installation": "pip install crewai or pip install 'crewai[tools]'",
      "Dependency_Management": {
        "Tool": "UV",
        "Commands": [
          "uv lock",
          "uv sync",
          "uv venv (optional)"
        ]
      },
      "Environment_Variables": [
        "OPENAI_API_KEY",
        "SERPER_API_KEY",
        "OTEL_SDK_DISABLED=true (optional)"
      ],
      "Static_Checks": "uvx mypy src",
      "Build_and_Install": [
        "uv build",
        "pip install dist/*.tar.gz"
      ],
      "PreCommit_Hooks": "pre-commit install"
    },
    "Dependencies": {
      "Main": [
        "pydantic>=2.4.2",
        "openai>=1.13.3",
        "uv>=0.4.25",
        "chromadb>=0.5.23",
        "pdfplumber>=0.11.4"
        ],
      "Optional_Groups": [
        "tools (crewai-tools)",
        "fastembed",
        "pandas",
        "mem0"
      ],
      "Test_and_Dev": [
        "pytest>=8.0.0",
        "pytest-vcr>=1.0.2",
        "pytest-asyncio>=0.23.7",
        "pytest-subprocess>=1.5.2",
        "ruff>=0.8.2",
        "mypy>=1.10.0",
        "pre-commit>=3.6.0",
        "mkdocs and related packages"
      ]
    },
    "CI_Test_Execution": {
      "Python_Version": "3.12.8",
      "Environment_Variables": {
        "OPENAI_API_KEY": "fake-api-key"
      },
      "Test_Command": "uv run pytest tests -vv"
    },
    "Test_Execution_Local": "uv run pytest ."
  },
  "terminate": true
}
